"python3 -c '
import os, re

files = []
for root, dirs, filenames in os.walk("/workspace/product/history"):
    for f in filenames:
        if not f.endswith(".md"): continue
        p = os.path.join(root, f)
        try:
            with open(p, "r", errors="ignore") as file:
                c = file.read()
                # find dates like 2026-08-2* or 2026-08-3* or 2026-09-* or "August 2*" or "August 3*" or "September"
                matches = re.findall(r"(?:2026-08-(?:2\d|3[01])|2026-09-\d\d|August (?:2\d|3[01])|September \d+)", c)
                if matches:
                    files.append((p, matches, c[:200]))
        except:
            pass

print(f"Total files with late August / September dates: {len(files)}")
for p, m, head in files[:30]:
    print(f"{p}: {m[:3]}")
'"

"python3 -c '
import os, re
from collections import Counter

cohorts = Counter()

for root, dirs, files in os.walk("/workspace/product/history/evidence"):
    for f in files:
        if not f.endswith(".md"): continue
        p = os.path.join(root, f)
        with open(p, "r", errors="ignore") as file:
            c = file.read()
            m_cohort = re.search(r"cohort\s*([^;\n\.]+)", c, re.IGNORECASE)
            if not m_cohort:
                m_cohort = re.search(r"Cohort:\s*([^\n\.]+)", c)
            if m_cohort:
                cohorts[m_cohort.group(1).strip()] += 1

for c, count in cohorts.most_common():
    if count < 10:
        print(f"  {c}: {count}")
